/*
 * prog27_soundex.c
 *
 * Re‑implementation of the original program’s observable behaviour.
 * The program expects a single command‑line argument.  If no argument
 * is supplied, or the argument is an empty string, it prints the
 * literal string "EMPTY".  Otherwise it prints the 4‑character
 * Soundex code for the argument (first letter followed by three
 * digits, padded with '0' as needed).
 *
 * The mapping used by the original binary matches the classic
 * Soundex rules:
 *
 *   B, F, P, V           -> 1
 *   C, G, J, K, Q, S, X, Z -> 2
 *   D, T                 -> 3
 *   L                    -> 4
 *   M, N                 -> 5
 *   R                    -> 6
 *   A, E, I, O, U, H, W, Y -> 0   (ignored)
 *
 * The implementation follows the same logic that the de‑compiled
 * code performed, but expressed in clear C.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

/* Return the Soundex digit for an uppercase alphabetic character.
 * The function returns 0 for letters that are ignored by Soundex. */
static int soundex_digit(char ch)
{
    switch (ch) {
        case 'B': case 'F': case 'P': case 'V': return 1;
        case 'C': case 'G': case 'J': case 'K':
        case 'Q': case 'S': case 'X': case 'Z': return 2;
        case 'D': case 'T':                     return 3;
        case 'L':                               return 4;
        case 'M': case 'N':                     return 5;
        case 'R':                               return 6;
        default:                                return 0;   /* A,E,I,O,U,H,W,Y and non‑letters */
    }
}

/* Build the Soundex code for the supplied string.
 * The result is stored in the 5‑byte buffer `out` (4 characters + NUL). */
static void build_soundex(const char *s, char out[5])
{
    /* First character (always kept, upper‑cased) */
    out[0] = (char)toupper((unsigned char)s[0]);

    int prev_digit = soundex_digit(out[0]);   /* digit of the first letter */
    int pos = 1;                              /* next position to fill (1..3) */

    for (size_t i = 1; s[i] != '\0' && pos < 4; ++i) {
        char c = s[i];

        /* Convert to upper case if it is a lower‑case letter */
        c = (char)toupper((unsigned char)c);

        /* Skip H and W (they are ignored completely) */
        if (c == 'H' || c == 'W')
            continue;

        int d = soundex_digit(c);
        if (d == 0)               /* vowels and other ignored letters */
            continue;
        if (d == prev_digit)      /* suppress duplicate digits */
            continue;

        out[pos++] = (char)('0' + d);
        prev_digit = d;
    }

    /* Pad with zeros if fewer than three digits were produced */
    while (pos < 4)
        out[pos++] = '0';

    out[4] = '\0';
}

int main(int argc, char *argv[])
{
    if (argc < 2 || argv[1][0] == '\0') {
        puts("EMPTY");
        return 0;
    }

    char code[5];
    build_soundex(argv[1], code);
    puts(code);
    return 0;
}
